import {completionFeedback} from './feedback.js';
import {icon,illustration} from './icons.js';
import {createLedgerUI} from './ledger-ui.js';
import {migrateLedger,materializeRecurring} from './ledger-model.js';
import {createMobileUI} from './mobile-ui.js';
import {createActivityStore} from './activity-store.js';
import {createRecordCalendar} from './record-calendar-ui.js';
import {appendActivity,snapshot} from './activity.js';
import {createActivityUI} from './activity-ui.js';
import {retryMutation} from './mutations.js';
import {createHomeSync} from './realtime.js';
import {ensureMembers,renameMember} from './members.js';
import {createPetManager} from './pet-manager.js';
import {client,rpc} from './cloud.js';
import {today,balance,expense,isIncome,recordAccount,empty,validData,normalizeNames,exerciseSummary,choreStatus,nextChoreDate,choreFrequency,choreRule,choreIcons,choreIcon,formatDate,formatDateTime,formatDatesInText,choreScheduleMode,migrateChores,choreCompletion,completeChore,commonChores,calculateAmount} from './model.js';
const $=s=>document.querySelector(s), key='our-home-v1';
let data=empty(),session=null,cloudHome=null,loading=true,busy=false,authBusy=false,loadedUserId=null,syncState='syncing';
const activityStore=createActivityStore({rpc,getHome:()=>cloudHome});
let pendingActivity=[];
const petManager=createPetManager({getData:()=>data,getHome:()=>cloudHome,getSession:()=>session,mutate,refresh:loadHome,render,openLegacy:open,today,toast,client,activity:activityStore,offerDoseUndo:(id,groupId)=>activityUI.offerDoseUndo(id,groupId),getMember:currentMember,removeRecord:(collection,id)=>activityUI.remove(collection,id)});
const activityUI=createActivityUI({getData:()=>data,getUserId:()=>session?.user.id,mutate,render,toast,activity:activityStore});
const ledgerUI=createLedgerUI({getData:()=>data,getMember:currentMember,getHomeId:()=>cloudHome?.id,mutate,removeRecord:(collection,id)=>activityUI.remove(collection,id),calculateAmount,today,toast});
const pages=[['home','home','首頁總覽'],['money','money','家庭帳本'],['pets','pets','寵物日記'],['chores','chores','家務排程'],['health','health','運動健康']];
let page='home',month=today().slice(0,7),person='',petFilter='',healthMonth=today().slice(0,7),healthDay='';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nt=n=>new Intl.NumberFormat('zh-TW',{maximumFractionDigits:2}).format(n);
const money=n=>'NT$ '+nt(n);const sorted=a=>[...a].sort((a,b)=>b.date.localeCompare(a.date));
const labelDate=d=>new Date(d+'T12:00:00').toLocaleDateString('zh-TW',{month:'long',day:'numeric',weekday:'short'});
const recordCalendar=createRecordCalendar({getData:()=>data,today,expense,balance,esc,open,render,petManager});
const mobileUI=createMobileUI({getPage:()=>page,getHome:()=>cloudHome,getTitle:()=>page==='home'?Number(recordCalendar.month().slice(5))+' 月':$('#view h1')?.textContent||'我們的家',isBusy:()=>busy||authBusy||Boolean($('#pet-modal [type="submit"]')?.disabled),onSettings:()=>open('settings'),getPet:()=>petManager.current(),onPetMenu:()=>petManager.profileMenu(),onAdd:kind=>{if(page==='home')recordCalendar.add(kind);else if(page==='pets')petManager.addCurrent();else open(({money:'money',chores:'chores',health:'health'})[page],page==='health'?{kind:'運動'}:{});}});
function inputFocused(){const active=document.activeElement;return Boolean(active?.isConnected&&active.matches('input,select,textarea,[contenteditable]:not([contenteditable="false"])')&&(!active.closest('dialog')||active.closest('dialog').open));}
function updateSync(){const offline=navigator.onLine===false||Boolean(session)&&syncState==='offline';mobileUI.setSync(offline?'offline':syncState==='offline'?'syncing':syncState);const notice=$('.local-notice');notice.hidden=!offline;notice.innerHTML=offline?'<span class="offline-dot" aria-hidden="true"></span><span>離線中，恢復連線後會自動同步</span>':'';}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500);}
function currentMember(){return data.members?.find(m=>m.userId===session?.user.id)||{userId:session?.user.id,name:'家庭成員',color:'#315c4c'};}
function displayPerson(record){return data.members?.find(m=>m.userId===record.personUserId)?.name||data.members?.find(m=>m.name===record.person)?.name||(record.person==='一起'?'一起':'未知成員');}
function matchesPerson(record,name){const member=data.members?.find(m=>m.name===name);return record.personUserId?record.personUserId===member?.userId:record.person===name;}
const memberNames=()=>data.members?.map(m=>m.name)||[];
function editingOpen(){return Boolean(document.querySelector('dialog[open]')||recordCalendar.isComposing());}
const homeSync=createHomeSync({client,getHome:()=>cloudHome,isBlocked:()=>busy||authBusy||loading||editingOpen()||inputFocused()||document.visibilityState==='hidden',load:()=>loadHome({deferIfEditing:true}),render,onState:state=>{syncState=state;updateSync();},onError:()=>toast('網路好像斷了，等一下會自動再試')});
async function save(){
 if(!cloudHome)throw Error('請先登入並建立或加入家庭');
 try{cloudHome.revision=await activityStore.save(snapshot(data),pendingActivity,cloudHome.revision);syncState='synced';updateSync();}catch(error){if(error.code!=='REVISION_CONFLICT'&&!/資料已更新|revision conflict/i.test(error.message)){syncState='offline';updateSync();}throw error;}
 // Realtime 僅傳 revision，不傳家庭資料。
 homeSync.connect();void homeSync.notify(cloudHome.revision);
}
async function mutate(fn,options={}){
 if(busy||authBusy){toast('正在記下來，稍等一下');return false;}
 busy=true;updateSync();const context={...options,id:options.id||crypto.randomUUID(),at:new Date().toISOString(),userId:session.user.id};
 const audited=()=>{const before=snapshot(data);fn();data.events=structuredClone(before.events);delete data.activity;pendingActivity=appendActivity(data,before,context);};
 try{await retryMutation({getData:()=>data,setData:value=>{data=value;},getHome:()=>cloudHome,loadHome,save,fn:audited,beforeAttempt:options.prepare,hasPendingActivity:()=>pendingActivity.length>0});activityUI.invalidate();await petManager.refreshActivity();render();return true;}
 catch(error){render();options.onError?.(error);toast(error.message);return false;}
 finally{pendingActivity=[];busy=false;updateSync();void homeSync.flush();}
}
function authView(){return heading('OUR HOME, TOGETHER','歡迎回家','登入後，與另一半一起照顧生活。')+`<div class="card auth-card"><form id="auth-form"><label class="field">Email<input type="email" name="email" autocomplete="email" required></label><label class="field">密碼<input type="password" name="password" autocomplete="current-password" minlength="8" required></label><div class="backup-buttons"><button class="primary" type="submit" name="action" value="login">登入</button><button class="subtle" type="submit" name="action" value="signup">建立帳號</button></div><p class="hint">你與另一半各自註冊帳號。首次註冊後，請到信箱完成驗證再回來登入。密碼至少 8 碼。</p><p id="auth-message" role="status"></p></form></div>`;}
function familyView(){return heading('ONE HOME, TWO HEARTS','建立我們的家','一人先建立家庭，再邀請另一半加入。')+`<div class="card auth-card"><p class="hint">已登入：${esc(session.user.email)}</p><div class="backup-buttons"><button class="primary" id="create-home">建立新家庭</button><button class="subtle" id="join-home">接受另一半的邀請</button><button class="subtle" id="account-settings">設定</button></div><p class="hint">若另一半已建立家庭，請先讓對方在「帳戶設定」輸入你的註冊 Email，再按接受邀請。每個帳號只能加入一個家庭。</p></div>`;}
function notice(){updateSync();$('#date-label').textContent=new Date().toLocaleDateString('zh-TW',{month:'long',day:'numeric',weekday:'long'}).replace('星期',' 星期');$('.brand-icon').innerHTML=icon('home');$('#modal .close').innerHTML=icon('close');$('.sidebar-decoration').innerHTML=icon('sparkle');$('#settings').innerHTML=icon('settings')+'<span>資料與帳戶設定</span>';}

async function loadHome({deferIfEditing=false}={}){
 const userId=session?.user.id;if(!userId)return;
 for(let attempt=0;attempt<4;attempt++){
  const result=await rpc('family_read');if(session?.user.id!==userId)return false;if(deferIfEditing&&(editingOpen()||inputFocused()||busy||authBusy)){void homeSync.request();return false;}
  if(result&&!validData(result.document))throw Error('雲端資料格式不相容，請勿覆寫，先聯絡維護者。');
  cloudHome=result;activityStore.ingest(result?.document);activityUI.invalidate();data=result?normalizeNames(result.document):empty();
  if(result){
   const oldMembers=JSON.stringify(data.members||[]);ensureMembers(data,result.memberRoster||[],userId,result.owner);
   if(oldMembers!==JSON.stringify(data.members)||data.chores.some(c=>!['completion','fixed'].includes(c.scheduleMode))){
    try{data=normalizeNames(result.document);const migration={id:crypto.randomUUID(),at:new Date().toISOString(),userId,summary:'更新成員與家務排程設定'};await retryMutation({getData:()=>data,setData:value=>{data=value;},getHome:()=>cloudHome,loadHome:async()=>{const fresh=await rpc('family_read');cloudHome=fresh;activityStore.ingest(fresh.document);data=normalizeNames(fresh.document);},save,fn:()=>{const before=snapshot(data);ensureMembers(data,result.memberRoster||[],userId,result.owner);migrateChores(data);pendingActivity=appendActivity(data,before,migration);}});}
    catch(error){if(/資料已更新|revision conflict/i.test(error.message)&&attempt<3)continue;throw error;}
   }
   if(data.financeVersion!==1){const context={id:crypto.randomUUID(),at:new Date().toISOString(),userId,ledgerMigration:true};await retryMutation({getData:()=>data,setData:value=>data=value,getHome:()=>cloudHome,loadHome:async()=>{const fresh=await rpc('family_read');cloudHome=fresh;activityStore.ingest(fresh.document);data=normalizeNames(fresh.document);},save,fn:()=>{const before=snapshot(data);if(migrateLedger(data))pendingActivity=appendActivity(data,before,context);else pendingActivity=[];}});}
   if(data.recurring?.some(r=>!r.paused)){const context={id:crypto.randomUUID(),at:new Date().toISOString(),userId,summary:'自動補入固定收支'};let generated;await retryMutation({getData:()=>data,setData:value=>data=value,getHome:()=>cloudHome,loadHome:async()=>{const fresh=await rpc('family_read');cloudHome=fresh;activityStore.ingest(fresh.document);data=normalizeNames(fresh.document);},save,fn:()=>{const before=snapshot(data);generated=materializeRecurring(data,today());pendingActivity=appendActivity(data,before,context);}});if(generated?.more)toast('固定收支一次最多補60筆，尚有待補紀錄，稍後同步會繼續。');}
   if(loadedUserId!==userId||!memberNames().includes(person)){person=currentMember().name;loadedUserId=userId;}
  }
  await petManager.refreshActivity();if(session?.user.id!==userId)return false;
  if(deferIfEditing&&(editingOpen()||inputFocused()||busy||authBusy)){void homeSync.request();return false;}homeSync.connect();syncState='synced';updateSync();return;
 }
}
async function initialize(){try{const result=await client.auth.getSession();if(result.error)throw result.error;session=result.data.session;if(session)await loadHome();}catch(error){if(session)syncState='offline';toast(error.message);}finally{loading=false;render();void homeSync.flush();}}
function heading(k,title,sub,action=''){return `<div class="page-heading"><div><p class="eyebrow">${k}</p><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;}
const add=(kind,label='＋ 新增紀錄')=>`<button class="primary" data-add="${kind}">${icon('add')}${label.replace(/^＋\s*/, '')}</button>`;
const emptyMsg=(t,art='')=>`<div class="empty empty-state">${art?illustration(art):''}<p>${t}</p></div>`;
const card=(title,body,link='')=>`<div class="card"><div class="section-title"><h2>${title}</h2>${link}</div>${body}</div>`;
const more=p=>`<a href="#${p}">查看全部 ↗</a>`;
function row(icon,title,sub,right='',extra=''){return `<div class="row"><div class="row-icon">${icon}</div><div class="row-main"><strong>${esc(title)}</strong><p>${esc(sub)}</p></div>${right}${extra}</div>`;}
const del=(kind,id)=>`<button class="delete" data-delete="${kind}" data-id="${esc(id)}" aria-label="刪除此紀錄">刪除</button>`;
const editRecordButton=(collection,id)=>`<button class="subtle" data-edit-record="${collection}" data-id="${esc(id)}">編輯</button>`;
function paymentLabel(record){const account=recordAccount(record);return account==='共同帳戶'?'共同帳戶':(data.members.find(m=>m.userId===account)?.name||'未知成員')+(isIncome(record)?'個人':'先付');}
function mobileMoneyRows(items){const days=new Map();for(const x of items){if(!days.has(x.date))days.set(x.date,[]);days.get(x.date).push(x);}return [...days].map(([date,entries])=>`<section class="money-day"><h3>${esc(formatDate(date))} · 支出 ${money(entries.filter(x=>x.kind==='支出').reduce((n,x)=>n+Number(x.amount),0))}</h3>${entries.map(x=>{const member=data.members.find(m=>m.userId===recordAccount(x)),color=/^#[0-9a-f]{6}$/i.test(member?.color)?member.color:'var(--muted)';return `<button type="button" class="money-entry" data-money-edit="${esc(x.id)}"><span class="money-entry-main"><strong>${x.recurringId?'<span class="recurring-mark" aria-label="固定收支">'+icon('recurring')+'</span>':''}${esc(x.title||x.category)}</strong><span class="money-caption">${esc(x.category+(x.subcategory?' › '+x.subcategory:''))} · <i style="background:${recordAccount(x)==='共同帳戶'?'var(--primary)':color}" aria-hidden="true"></i>${esc(paymentLabel(x))}</span></span><span class="row-amount ${isIncome(x)?'positive':''}">${isIncome(x)?'+':'−'}${money(x.amount)}</span></button>`;}).join('')}</section>`).join('');}
function moneyRows(items,remove=false){if(mobileUI.mobile())return items.length?mobileMoneyRows(items):emptyMsg('這個月還沒有花費，真省。想記一筆時，我們再慢慢記。','wallet');return items.length?items.map(x=>row(x.recurringId?icon('recurring'):icon('money'),x.title||x.category,`${formatDate(x.date)} · ${x.category+(x.subcategory?' › '+x.subcategory:'')+' · '+paymentLabel(x)}${x.note?' · '+x.note:''}`,`<span class="row-amount ${isIncome(x)?'positive':''}">${isIncome(x)?'+':'−'}${nt(x.amount)}</span>`,remove?editRecordButton('money',x.id)+del('money',x.id):'')).join(''):emptyMsg('從第一筆開始，慢慢把生活記下來。','wallet');}
function categoryChart(){const groups=new Map();for(const r of data.money.filter(x=>x.kind==='支出'&&x.date.startsWith(month))){const group=groups.get(r.category)||{total:0,sub:new Map()};group.total+=Number(r.amount);const name=r.subcategory||'未分類';group.sub.set(name,(group.sub.get(name)||0)+Number(r.amount));groups.set(r.category,group);}return groups.size?[...groups].sort((a,b)=>b[1].total-a[1].total).map(([name,g])=>`<details class="category-stats"><summary>${esc(name)} <b>${money(g.total)}</b></summary>${[...g.sub].map(([label,amount])=>`<div class="chart-row"><span>${esc(label)}</span><b>${money(amount)}</b></div>`).join('')}</details>`).join(''):emptyMsg('記下支出後，就能看見錢花在哪裡。');}
function overview(){const deposits=data.money.filter(x=>isIncome(x)&&x.date.startsWith(month)).reduce((s,x)=>s+Number(x.amount),0);return `<div class="mobile-money-summary card balance"><div>共同帳戶餘額</div><div class="amount">${money(balance(data))}</div><div class="mobile-money-totals"><span>本月支出<br><b>${money(expense(data,month))}</b></span><span>本月收入<br><b>${money(deposits)}</b></span></div></div><div class="overview"><div class="card balance"><div class="card-label">共同帳戶餘額 <span>OUR FAMILY FUND</span></div><div class="amount"><small>NT$</small>${nt(balance(data))}</div><div class="card-foot">${balance(data)<data.threshold?'◉ 餘額低於 '+money(data.threshold)+'，記得補充家庭基金。':'一起存下的，是生活的安心。'}</div></div><div class="card"><div class="card-label">本月家庭支出 <span>↗</span></div><div class="amount"><small>NT$</small>${nt(expense(data,month))}</div><div class="card-foot">包含共同帳戶與個人支付</div></div><div class="card"><div class="card-label">本月收入 <span>↙</span></div><div class="amount"><small>NT$</small>${nt(deposits)}</div><div class="card-foot">每一份投入，都是一起的生活</div></div></div>`;}
function infoButton(text){return `<button type="button" class="info-button" data-info="${esc(text)}" aria-label="使用說明">${icon('info')}</button>`;}
function exercisePanel(){return `<div class="card exercise"><div class="section-title"><h2>${icon('health')} 今天，一起動一動</h2><span class="tag">每天動一點</span></div><p>散步、重訓、瑜珈，都算好好照顧自己。<br>記下今天做的運動、時間，還有手錶上的數據。</p><div class="exercise-actions">${memberNames().map(p=>{const records=data.health.filter(x=>x.kind==='運動'&&matchesPerson(x,p)&&x.date===today());const minutes=records.reduce((n,x)=>n+Number(x.minutes||0),0);return `<button data-exercise="${esc(p)}" class="${records.length?'done':''}">＋ ${esc(p)}${records.length?'今天 '+nt(minutes)+' 分鐘 · 再記一筆':'記錄運動'}</button>`;}).join('')}</div></div>`;}
function home(){return recordCalendar.page();}
function monthPicker(value,kind){const [y,m]=value.split('-').map(Number);return `<div class="record-month-nav page-month-picker"><button class="subtle" data-page-month="${kind}" data-step="-1" aria-label="上個月">${icon('back')}</button><h2>${y}年${m}月</h2><button class="subtle" data-page-month="${kind}" data-step="1" aria-label="下個月">${icon('next')}</button></div>`;}
function moneyPage(){return heading('FAMILY FINANCES','家庭帳本','看見每一筆開銷，也看見一起累積的安心。',add('money','＋ 記一筆'))+`<div class="toolbar">${monthPicker(month,'money')}<button class="subtle calculator-launch" id="open-calculator" aria-label="計算機"><span class="desktop-only">計算機</span><span class="mobile-only">${icon('calculator')}</span></button><button class="subtle" id="open-recurring" aria-label="固定收支">${icon('recurring')}</button><button class="subtle desktop-only" data-settings>帳戶設定與備份</button></div>`+overview()+(data.money.some(x=>x.date.startsWith(month))?`<div class="layout"><div>${card('收支明細',moneyRows(sorted(data.money).filter(x=>x.date.startsWith(month)),true))}</div>${data.money.some(x=>x.kind==='支出'&&x.date.startsWith(month))?card('支出分類',categoryChart()):''}</div>`:card('家庭帳本',emptyMsg('這個月還沒有花費，真省。想記一筆時，我們再慢慢記。','wallet')));}
function petPage(){return petManager.page();}
function choreRows(items,actions=false){return items.map(x=>{const {days}=choreStatus(x),tier=days<0?'overdue':days<=3?'soon':'later',last=(x.history||[]).at(-1),done=choreCompletion(data,last||x.date);if(mobileUI.mobile())return `<div class="row chore-row compact-chore" role="button" tabindex="0" data-chore-detail="${esc(x.id)}" aria-label="${esc(x.title)}詳細資料"><span class="row-icon">${choreIcon(x)}</span><div class="row-main"><strong>${esc(x.title)}${x.pinned?'<span class="pinned-mark" title="已置頂">'+icon('pin')+'</span>':''}</strong><p class="chore-status-${tier}">${days<0?'逾期 '+(-days)+' 天':days===0?'今天到期':'還有 '+days+' 天'} · 上次 ${esc(done.date?done.name:'尚未完成')}</p></div><button class="chore-check" data-complete="${esc(x.id)}" aria-label="完成${esc(x.title)}">${icon('check')}</button></div>`;return `<div class="row chore-row"><div class="row-icon">${choreIcon(x)}</div><div class="row-main"><strong><a href="#chores/${encodeURIComponent(x.id)}">${esc(x.title)}</a>${x.pinned?'<span class="pinned-mark" title="已置頂">'+icon('pin')+'</span>':''}</strong><p>${esc(choreFrequency(x))} · ${choreScheduleMode(x)==='completion'?'從完成日起算':'固定日期'} · 下次 ${esc(formatDate(x.next))}</p><span class="tag chore-status-${tier}">${days<0?'逾期 '+(-days)+' 天':days===0?'今天到期':'還有 '+days+' 天'}</span><p class="hint">${done.date?'上次由 '+esc(done.name)+' 完成 · '+esc(formatDate(done.date)):'尚未完成第一次'}</p></div><div class="chore-actions"><button class="subtle" data-complete="${esc(x.id)}">完成這次</button>${actions?`<button class="delete" data-pin-chore="${esc(x.id)}">${x.pinned?'取消置頂':'☆ 置頂'}</button><button class="delete" data-edit-chore="${esc(x.id)}">編輯</button>${del('chores',x.id)}`:''}</div></div>`;}).join('');}
function chorePage(){
 let id='';try{id=decodeURIComponent(location.hash.split('/')[1]||'');}catch{}
 const chore=data.chores.find(c=>c.id===id);
 if(chore){const history=[...(chore.history||[])].reverse();return heading('OUR EVERYDAY CARE',esc(chore.title),'查看排程與每次完成紀錄。','<a href="#chores">'+icon('back')+' 返回全部家務</a>')+card('家務安排',choreRows([chore],true))+card('完成紀錄',history.length?history.map(h=>{const done=choreCompletion(data,h);return row('✓',done.name+'完成',formatDate(done.date));}).join(''):emptyMsg('尚未有完成紀錄。'));}
 const title=heading('A PLACE FOR EVERY LITTLE TASK',mobileUI.mobile()?'家務':'固定家務排程','把需要照顧的事，安排在剛好的時候。',add('chores','＋ 新增固定家務'));
 if(!data.chores.length)return title+`<div class="card empty empty-state">${illustration('plant')}<p>家裡的事，慢慢一起照顧。先加幾項常用家務吧。</p><button class="primary" id="seed-chores">一鍵加入常用家務</button></div>`;
 const items=[...data.chores].sort((a,b)=>Number(Boolean(b.pinned))-Number(Boolean(a.pinned))||a.next.localeCompare(b.next));return title+card('家務安排',choreRows(items,true));
}
function trend(items,field,label){const points=items.filter(x=>Number(x[field])>0).slice(-12);if(!points.length)return `<p class="empty">${label}：尚無數據</p>`;const nums=points.map(x=>Number(x[field])),min=Math.min(...nums)-1,max=Math.max(...nums)+1;const coords=nums.map((n,i)=>`${20+i*260/Math.max(nums.length-1,1)},${105-(n-min)/(max-min)*85}`).join(' ');return `<p class="hint">${label} · 最近 ${points.length} 次 · ${esc(formatDate(points[0].date))} 至 ${esc(formatDate(points.at(-1).date))}</p><svg class="trend" viewBox="0 0 300 130" role="img" aria-label="${label}趨勢"><path d="M20 110H285" stroke="var(--line)"/><polyline points="${coords}" fill="none" stroke="var(--category-health)" stroke-width="2.5"/>${coords.split(' ').map((p,i)=>{const [x,y]=p.split(',');return `<circle cx="${x}" cy="${y}" r="3" fill="var(--primary)"/><text x="${x}" y="${Number(y)-9}" text-anchor="middle" font-size="9" fill="var(--muted)">${nums[i]}</text>`;}).join('')}</svg>`;}
function exerciseDetails(x){return [formatDate(x.date),x.time,x.activeCalories!==''&&x.activeCalories!=null?'動態熱量 '+x.activeCalories+' kcal':'',x.totalCalories!==''&&x.totalCalories!=null?'總熱量 '+x.totalCalories+' kcal':'',x.avgHeartRate?'平均心率 '+x.avgHeartRate+' bpm':'',x.distance?'距離 '+x.distance+' km':'',x.intensity?'強度 '+x.intensity:'',x.note].filter(Boolean).join(' · ');}
function healthEdit(x){return `<button class="subtle" data-edit-health="${esc(x.id)}">編輯</button>`+del('health',x.id);}
function exerciseCalendar(items){const [y,m]=healthMonth.split('-').map(Number),count=new Date(y,m,0).getDate(),offset=new Date(y,m-1,1).getDay();return `<div class="calendar exercise-calendar">${['日','一','二','三','四','五','六'].map(d=>`<div class="day-name">${d}</div>`).join('')}${'<div></div>'.repeat(offset)}${Array.from({length:count},(_,i)=>{const d=healthMonth+'-'+String(i+1).padStart(2,'0'),entries=items.filter(x=>x.date===d);return `<button class="day ${d===today()?'today':''} ${healthDay===d?'selected':''}" data-health-day="${d}" aria-label="${d}，${entries.length} 筆運動">${i+1}${entries.length?`<small>${nt(entries.reduce((n,x)=>n+Number(x.minutes||0),0))} 分鐘</small><span class="hint">${entries.length} 筆</span>`:''}</button>`;}).join('')}</div>`;}
function healthPage(){
 const all=sorted(data.health).filter(x=>matchesPerson(x,person)),summary=exerciseSummary(data.health,person,healthMonth,data.members.find(m=>m.name===person)?.userId),items=sorted(summary.items).filter(x=>!healthDay||x.date===healthDay),body=all.filter(x=>x.kind==='InBody').reverse(),latest=body.at(-1),previous=body.at(-2),bodyMonth=all.filter(x=>x.kind==='InBody'&&x.date.startsWith(healthMonth));
 const help='Apple Watch 數據目前採手動填寫，沒有自動連接 Apple 健康。請填該次運動的數據，動態熱量不與總熱量相加。InBody 用來觀察趨勢，不作健康診斷。';
 const title=heading('MOVE YOUR OWN WAY','運動健康','今天做了什麼、動了多久，照自己的步調記錄。',`<div>${infoButton(help)}${add('health','＋ 新增紀錄')}</div>`)+`<div class="toolbar"><label>查看成員<select id="health-person" aria-label="查看誰的健康紀錄">${memberNames().map(n=>`<option ${person===n?'selected':''}>${esc(n)}</option>`).join('')}</select></label>${monthPicker(healthMonth,'health')}</div>`;
 if(!all.length)return title+card('運動與體態',emptyMsg('今天動一點就很好，散步也算喔。','shoes'));
 const stats=[['運動天數',summary.days+' 天'],['運動次數',summary.sessions+' 次'],['運動總時間',nt(summary.minutes)+' 分鐘'],['動態熱量',summary.calorieEntries?nt(summary.activeCalories)+' kcal':'尚未記錄']];
 let result=title;
 if(summary.items.length)result+=`<div class="stats-grid exercise-stats">${stats.map(([t,v])=>`<div class="card"><div class="card-label">${t}</div><div class="amount">${esc(v)}</div></div>`).join('')}</div><div class="layout"><div class="stack">${card('本月運動足跡',exerciseCalendar(summary.items))}${exercisePanel()}</div>${card(healthDay?formatDate(healthDay)+' 的運動':'整月運動紀錄',`${healthDay?'<button class="subtle" id="all-health-days">顯示整個月</button>':''}${items.length?items.map(x=>row(icon('health'),x.title+' · '+x.minutes+' 分鐘',exerciseDetails(x),'',healthEdit(x))).join(''):emptyMsg('這一天還沒有運動紀錄。')}`)}</div>`;
 if(body.length)result+=`<div class="layout"><div>${card('InBody 體態趨勢（所有月份）',`<p class="hint">最近測量 ${esc(formatDate(latest.date))} · ${esc(latest.weight)} kg</p>`+trend(body,'weight','體重 kg')+(body.some(x=>Number(x.muscle)>0)?trend(body,'muscle','骨骼肌量 kg'):'')+(body.some(x=>Number(x.fat)>0)?trend(body,'fat','體脂率 %'):'')+(previous?`<p class="hint">比上次：體重 ${Number((latest.weight-previous.weight).toFixed(1))} kg</p>`:''))}</div>${bodyMonth.length?card('InBody 紀錄（所選月份）',bodyMonth.map(x=>row(icon('health'),'InBody · '+x.weight+' kg',`${formatDate(x.date)} · 骨骼肌 ${x.muscle||'—'} kg · 體脂 ${x.fat||'—'}%${x.fatMass?' · 脂肪量 '+x.fatMass+' kg':''}${x.visceral?' · 內臟脂肪 '+x.visceral:''}${x.bmr?' · 基礎代謝 '+x.bmr+' kcal':''}${x.note?' · '+x.note:''}`,'',healthEdit(x))).join('')):''}</div>`;
 if(!summary.items.length&&!bodyMonth.length)result+=card('本月紀錄',emptyMsg('這個月還沒記下來，今天動一點就很好。','shoes'));
 return result;
}
function render(){notice();if(loading){$('#view').innerHTML=emptyMsg('正在連接家庭資料…');return;}if(!session){mobileUI.refresh();$('#nav').innerHTML='';$('#view').innerHTML=authView();return;}if(!cloudHome){mobileUI.refresh();$('#nav').innerHTML='';$('#view').innerHTML=familyView();return;}if(location.hash==='#calendar')history.replaceState(null,'','#home');page=(location.hash.slice(1)||'home').split('/')[0];if(!pages.some(x=>x[0]===page)&&page!=='activity')page='home';$('#nav').innerHTML=pages.map(([id,key,title])=>`<a href="#${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(key)}${title}</a>`).join('');$('#view').innerHTML=({home,money:moneyPage,pets:petPage,chores:chorePage,health:healthPage,activity:activityUI.page}[page])();petManager.mountPhotos().catch(()=>{});focusRouteRecord();mobileUI.refresh();updateSync();}
function focusRouteRecord(){const route=location.hash.slice(1).split('/');let id;try{id=decodeURIComponent(route[0]==='pets'?route[3]||'':route[0]==='chores'?route[1]||'':'');}catch{return;}if(!id)return;if(route[0]==='pets'){petManager.focusRecord(id);return;}const button=[...document.querySelectorAll('[data-complete]')].find(e=>e.dataset.complete===id),row=button?.closest('.row');if(row){row.classList.add('record-highlight');row.tabIndex=-1;row.focus({preventScroll:true});row.scrollIntoView?.({block:'center',behavior:'smooth'});}}
const field=(name,label,type='text',value='',required=true)=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'min="0" step="0.1"':''} ${type==='text'?'maxlength="300"':''}></label>`;
const select=(name,label,options,value='')=>`<label class="field">${label}<select name="${name}">${options.map(x=>`<option ${x===value?'selected':''}>${esc(x)}</option>`).join('')}</select></label>`;
const notes=value=>`<label class="field">備註<textarea name="note" rows="3" maxlength="3000">${esc(value||'')}</textarea></label>`;
let editingKind='',editingId=null,prefill={};
function calculatorPanel(standalone=false){return `<div class="calculator" data-standalone="${standalone}"><label class="field">輸入算式<input id="calc-expression" type="text" inputmode="decimal" maxlength="120" placeholder="例如：120 + 85 × 2" autocomplete="off" aria-describedby="calc-hint"></label><output id="calc-output" aria-live="polite">0</output><p id="calc-error" role="alert"></p><div class="calc-keys">${[['AC','清除'],['⌫','退一格'],['(','左括號'],[')','右括號'],['7','7'],['8','8'],['9','9'],['÷','除'],['4','4'],['5','5'],['6','6'],['×','乘'],['1','1'],['2','2'],['3','3'],['−','減'],['0','0'],['.','小數點'],['=','等於'],['+','加']].map(([k,label])=>`<button type="button" data-calc-key="${k}" aria-label="${label}" class="${k==='='?'calc-equals':''}">${k}</button>`).join('')}</div><p class="hint" id="calc-hint">先乘除後加減，可使用括號；結果四捨五入到小數第 2 位。</p><button type="button" class="primary calc-apply" id="calc-apply">${standalone?'用這個結果記一筆':'帶入記帳金額'}</button></div>`;}
function computeCalculator(){try{const result=calculateAmount($('#calc-expression').value);$('#calc-output').textContent=String(result);$('#calc-error').textContent='';return result;}catch(error){$('#calc-output').textContent='—';$('#calc-error').textContent=error.message;return null;}}
function calculatorClick(b){
 if(b.id==='open-calculator'){open('calculator');return true;}
 if(b.dataset.calcKey!==undefined){const input=$('#calc-expression'),k=b.dataset.calcKey;if(k==='='){computeCalculator();return true;}if(k==='AC'){input.value='';$('#calc-output').textContent='0';}else if(k==='⌫'){const start=input.selectionStart??input.value.length,end=input.selectionEnd??start;input.setRangeText('',start===end?Math.max(0,start-1):start,end,'end');}else{const start=input.selectionStart??input.value.length,end=input.selectionEnd??start;if(input.value.length-(end-start)+k.length<=120)input.setRangeText(k,start,end,'end');}$('#calc-error').textContent='';return true;}
 if(b.id==='calc-apply'){const value=computeCalculator();if(value===null)return true;if(value<=0){$('#calc-error').textContent='記帳金額須大於 0，請調整算式。';return true;}if(editingKind==='calculator'){$('#modal').close();open('money',{amount:value});}else{$('[name="amount"]').value=String(value);$('#calc-details').open=false;$('[name="amount"]').focus();}return true;}
 return false;
}
function choreIconFields(v){return `<input type="hidden" name="icon" value="${choreIcon(v)}" data-manual="${Boolean(v.icon)}"><div class="chore-icon-choices" aria-label="家務圖示">${choreIcons.map(([icon,label])=>`<button type="button" data-chore-icon="${icon}" class="${choreIcon(v)===icon?'selected':''}" aria-label="${label}">${icon}<small>${label}</small></button>`).join('')}</div>`;}
